import sys
sys.setrecursionlimit(10000)
N=6
size=N*N
moves=[(2,1),(1,2),(-1,2),(-2,1),(-2,-1),(-1,-2),(1,-2),(2,-1)]
# precompute adjacency
adj=[[] for _ in range(size)]
for r in range(N):
    for c in range(N):
        i=r*N+c
        for dr,dc in moves:
            nr, nc = r+dr, c+dc
            if 0<=nr<N and 0<=nc<N:
                adj[i].append(nr*N+nc)
# fixed positions dict index->value
fixed={3:17,6:24,17:30,19:6,29:25,32:21,34:23}
solution=[-1]*size
solution[0]=0
used=[False]*size
used[0]=True
# apply fixed if they conflict with start
for idx,val in fixed.items():
    if idx==0:
        if val!=0:
            print('conflict')
            sys.exit()
    # will set later

def backtrack(pos):
    if pos==size:
        return True
    # if this position is fixed, must use that value
    if pos in fixed:
        cand=[fixed[pos]]
    else:
        # candidates are unused neighbors of previous cell
        prev=solution[pos-1]
        cand=[v for v in adj[prev] if not used[v]]
    # heuristic: sort by degree (Warnsdorff)
    def deg(v):
        return sum(1 for nb in adj[v] if not used[nb])
    cand.sort(key=deg)
    for v in cand:
        if used[v]: continue
        solution[pos]=v
        used[v]=True
        if backtrack(pos+1):
            return True
        used[v]=False
        solution[pos]=-1
    return False

